#!/usr/bin/env bun
import { describe, it } from "bun:test";
/**
 * Plan 239 Task 7: short-mode soak gate for long-running sessions (2,000 turns, ratio budgets only).
 * Full 10,000-turn evidence is generated by `bun scripts/benchmark-long-job.mjs --runs 200 --turns 50 --out docs/_evidence/long-run-soak.md`.
 */
import assert from "node:assert/strict";
import { runLongJobBenchmark } from "./benchmark-long-job.mjs";
import { checkCeiling, loadBudgets } from "./budget-gates.mjs";

const { fixture, ceilings } = loadBudgets().longRun;

let shortReportPromise;
function shortReport() {
  shortReportPromise ??= runLongJobBenchmark({
    runs: fixture.shortRuns,
    turns: fixture.shortTurns,
    jsonlRuns: 0,
    payloadBytes: fixture.payloadBytes,
    contextWindow: fixture.contextWindow,
  });
  return shortReportPromise;
}

describe("long-run soak budgets (plan 239 Task 7)", () => {
  it("long_session_turn_overhead_stays_flat", async () => {
    const report = await shortReport();
    assert.equal(report.environment.network, false);
    assert.equal(report.environment.credentials, false);
    assert.equal(report.fixture.totalTurns, fixture.shortRuns * fixture.shortTurns);
    const sqlite = report.results.find((entry) => entry.name === "sqlite");
    assert.ok(sqlite, "sqlite soak leg must run");
    assert.equal(sqlite.failedRuns, 0);
    assert.ok(sqlite.compactions > 0, "default compactor must run during the soak");

    const overhead = checkCeiling("sqlite.turnOverheadRatio", sqlite.turnOverheadRatio, ceilings.maxTurnOverheadRatio);
    assert.ok(overhead.ok, overhead.message);
    const reads = checkCeiling("sqlite.storeReadGrowthRatio", sqlite.storeReadGrowthRatio, ceilings.maxStoreReadGrowthRatio);
    assert.ok(reads.ok, reads.message);
  });

  it("long_session_heap_stays_flat", async () => {
    const report = await shortReport();
    const sqlite = report.results.find((entry) => entry.name === "sqlite");
    assert.ok(sqlite, "sqlite soak leg must run");
    const heap = checkCeiling("sqlite.heapGrowthRatio", sqlite.heapGrowthRatio, ceilings.maxHeapGrowthRatio);
    assert.ok(heap.ok, heap.message);
  });
});
